const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
  sword: 100,
};

const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type];

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const { items } = scenario.steps[0] as QuoteStep;
  const basePremium = items.reduce((total, item) => total + basePremiumOf(item), 0);

  return { results: [{ premium: basePremium + PROCESSING_FEE }] };
};
